from pathlib import Path
import random,json,hashlib
p=Path('/tmp/sirkit_hash_set_20261022');d=p/'cases';d.mkdir(exist_ok=True);rng=random.Random(20261022);rows=[]
def save(id,name,inp,out,kind):
 f=d/(name+'.in');g=f.with_suffix('.ans');f.write_text(inp);g.write_text(out);rows.append(dict(id=id,name=name,input=str(f),answer=str(g),kind=kind,input_sha256=hashlib.sha256(f.read_bytes()).hexdigest(),answer_sha256=hashlib.sha256(g.read_bytes()).hexdigest()))
group=json.loads(Path('Verify/current/groups/dynamic_hash.json').read_text())
for e in group['entries']:
 if e['id'] in ['hash_set_membership','hash_set_toggle','hash_set_strings']:
  for i,s in enumerate(e['samples']):save(e['id'],e['id']+f'_sample{i+1}',s['input'],s['output'],'official_public_sample')
def sums(name,a,b,c,mode,q=200000):
 values={x+y+z for x in a for y in b for z in c};ordered=sorted(values)
 if mode=='hit':xs=[ordered[rng.randrange(len(ordered))] for _ in range(q)]
 elif mode=='miss':xs=[rng.randrange(150000000,300000001) for _ in range(q)]
 elif mode=='boundary':xs=[0,1,100000000,200000000,300000000,299999999]
 else:xs=[ordered[rng.randrange(len(ordered))] if i%2 else rng.randrange(300000001) for i in range(q)]
 inp=''.join(str(len(v))+'\n'+' '.join(map(str,v))+'\n' for v in [a,b,c])+str(len(xs))+'\n'+' '.join(map(str,xs))+'\n';out=''.join('Yes\n' if x in values else 'No\n' for x in xs);save('hash_set_membership','sums_'+name,inp,out,'locally_generated_python_set_reference')
sums('boundary',[0,100000000],[0,100000000],[0,100000000],'boundary')
sums('small',[0],[0],[0],'mixed',1000)
sums('duplicates',[i%8 for i in range(100)],[i%8 for i in range(100)],[i%8 for i in range(100)],'mixed')
sums('arithmetic',[i*1000000 for i in range(100)],[i*1000 for i in range(100)],list(range(100)),'mixed')
sums('random',[rng.randrange(100000001) for _ in range(100)],[rng.randrange(100000001) for _ in range(100)],[rng.randrange(100000001) for _ in range(100)],'mixed')
sums('all_hit',[rng.randrange(100000001) for _ in range(100)],[rng.randrange(100000001) for _ in range(100)],[rng.randrange(100000001) for _ in range(100)],'hit')
sums('all_miss',[rng.randrange(1000000) for _ in range(100)],[rng.randrange(1000000) for _ in range(100)],[rng.randrange(1000000) for _ in range(100)],'miss')
def toggle(name,keys):
 values=set()
 for k in keys:
  if k in values:values.remove(k)
  else:values.add(k)
 save('hash_set_toggle','toggle_'+name,str(len(keys))+'\n'+'\n'.join(map(str,keys))+'\n',str(len(values))+'\n','locally_generated_python_set_reference')
toggle('single',[1000000000]);toggle('all_same',[1]*100000);toggle('random',[rng.randrange(1,1000000001) for _ in range(100000)]);toggle('repeated',[rng.randrange(1,1001) for _ in range(100000)]);half=rng.sample(range(1,1000000001),50000);toggle('two_halves',half+half);toggle('cycles',list(range(1,10001))*10)
def word(i,n=10):
 a=[]
 for _ in range(n):a.append(chr(97+i%26));i//=26
 return ''.join(a)
def strings(name,keys):save('hash_set_strings','strings_'+name,str(len(keys))+'\n'+'\n'.join(keys)+'\n',str(len(set(keys)))+'\n','locally_generated_python_set_reference')
strings('single',['a']);strings('unique',[word(i) for i in range(200000)]);strings('all_same',['aaaaaaaaaa']*200000);strings('prefix',['aaaaa'+word(i,5) for i in range(200000)]);strings('mixed',[word(rng.randrange(1000000),rng.randrange(1,11)) for _ in range(200000)])
(p/'cases.json').write_text(json.dumps(rows,indent=2));print('Generated',len(rows),'cases; officialsamples7, localindependent18')
